from abc import ABC, abstractmethod
from typing import List, TypeVar, Generic

T = TypeVar('T')

class SortAlgorithm(ABC, Generic[T]):
    """Abstract class defining the template for sorting algorithms"""

    def sort(self, data: List[T]) -> List[T]:
        """Template method that defines the sorting skeleton"""
        if len(data) <= 1:
            return data

        # Make a copy to avoid modifying the original
        sorted_data = data.copy()

        # Call the specific sorting algorithm implementation
        self._sort_impl(sorted_data)

        return sorted_data

    @abstractmethod
    def _sort_impl(self, data: List[T]) -> None:
        """Abstract method to be implemented by subclasses"""
        pass

    @abstractmethod
    def compare(self, a: T, b: T) -> bool:
        """Abstract method to compare elements"""
        pass

    @abstractmethod
    def swap(self, data: List[T], i: int, j: int) -> None:
        """Abstract method to swap elements"""
        pass


class BubbleSort(SortAlgorithm[T]):
    """Concrete implementation of Bubble Sort"""

    def _sort_impl(self, data: List[T]) -> None:
        n = len(data)
        for i in range(n - 1):
            for j in range(0, n - i - 1):
                if self.compare(data[j], data[j + 1]):
                    self.swap(data, j, j + 1)

    def compare(self, a: T, b: T) -> bool:
        """Compare if a > b (for ascending order)"""
        return a > b

    def swap(self, data: List[T], i: int, j: int) -> None:
        """Swap elements at positions i and j"""
        data[i], data[j] = data[j], data[i]


class SelectionSort(SortAlgorithm[T]):
    """Concrete implementation of Selection Sort"""

    def _sort_impl(self, data: List[T]) -> None:
        n = len(data)
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if self.compare(data[min_idx], data[j]):
                    min_idx = j
            if min_idx != i:
                self.swap(data, i, min_idx)

    def compare(self, a: T, b: T) -> bool:
        """Compare if a > b (for ascending order)"""
        return a > b

    def swap(self, data: List[T], i: int, j: int) -> None:
        """Swap elements at positions i and j"""
        data[i], data[j] = data[j], data[i]


class InsertionSort(SortAlgorithm[T]):
    """Concrete implementation of Insertion Sort"""

    def _sort_impl(self, data: List[T]) -> None:
        n = len(data)
        for i in range(1, n):
            key = data[i]
            j = i - 1

            # Move elements that are greater than key
            while j >= 0 and self.compare(data[j], key):
                data[j + 1] = data[j]
                j -= 1
            data[j + 1] = key

    def compare(self, a: T, b: T) -> bool:
        """Compare if a > b (for ascending order)"""
        return a > b

    def swap(self, data: List[T], i: int, j: int) -> None:
        """Swap elements at positions i and j"""
        data[i], data[j] = data[j], data[i]


